$totalFiles = ($files | Measure-Object).Count
$totalLines = ($files | Get-Content | Measure-Object -Line).Lines
Write-Output ("files=" + $totalFiles)
Write-Output ("lines=" + $totalLines)
if ($totalFiles -gt 0) {
  Write-Output ("avg=" + [math]::Round($totalLines / $totalFiles, 1))
}
Write-Output "--- per file ---"
foreach ($f in $files) {
  $n = (Get-Content -Path $f.FullName | Measure-Object -Line).Lines
  Write-Output ("{0,-60} {1,6}" -f $f.FullName, $n)
}
Write-Output "--- per crate ---"
Get-ChildItem -Path crates -Directory | ForEach-Object {
  $cf = Get-ChildItem -Path $_.FullName -Recurse -Filter *.rs -File
  $cl = ($cf | Get-Content | Measure-Object -Line).Lines
  Write-Output ("{0,-30} files={1,4} lines={2,6}" -f $_.Name, ($cf | Measure-Object).Count, $cl)
}
"}

