#[derive(Parser)]
#[command(name = "samho", version, about = "面向 Object 的 Rust Agent 运行时")]
struct Cli {
    #[arg(long, global = true)]
    config: Option<PathBuf>,
    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// 在本地运行任务；默认 Provider 是明确标注的模拟器。
    Run(RunArgs),
    /// 在本机提供共享 Agent API 与网页工作台。
